from __future__ import annotations

from datetime import datetime, timezone, timedelta

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus
from tasks_api.queries import TaskPage, TaskQuery, TaskQueryError, apply_query


NOW = datetime(2025, 6, 15, 12, 0, 0, tzinfo=timezone.utc)


def _task(id, title="task", status=TaskStatus.PENDING, priority=TaskPriority.MEDIUM,
          due_at=None, tags=None, created_at=None):
    return Task(
        id=id, title=title, status=status, priority=priority,
        due_at=due_at, tags=tags or [],
        created_at=created_at or NOW,
    )


# ── TaskQuery validation ────────────────────────────────────────────────

class TestTaskQueryValidation:
    def test_defaults(self):
        q = TaskQuery()
        assert q.sort == "created_at"
        assert q.limit == 20
        assert q.offset == 0
        assert q.descending is False

    def test_invalid_sort_field(self):
        with pytest.raises(TaskQueryError):
            TaskQuery(sort="invalid")

    def test_limit_zero(self):
        with pytest.raises(TaskQueryError):
            TaskQuery(limit=0)

    def test_limit_negative(self):
        with pytest.raises(TaskQueryError):
            TaskQuery(limit=-1)

    def test_limit_too_large(self):
        with pytest.raises(TaskQueryError):
            TaskQuery(limit=101)

    def test_offset_negative(self):
        with pytest.raises(TaskQueryError):
            TaskQuery(offset=-1)

    def test_tag_is_normalized(self):
        q = TaskQuery(tag="  Work  ")
        assert q.tag == "work"

    def test_invalid_tag_raises(self):
        with pytest.raises(ValueError):
            TaskQuery(tag="bad tag!")

    def test_search_stripped(self):
        q = TaskQuery(search="  hello  ")
        assert q.search == "hello"

    def test_search_whitespace_becomes_none(self):
        q = TaskQuery(search="   ")
        assert q.search is None


# ── apply_query — filtering ─────────────────────────────────────────────

class TestApplyQueryFiltering:
    @pytest.fixture
    def tasks(self):
        past = NOW - timedelta(days=30)
        future = NOW + timedelta(days=30)
        return [
            _task(1, "Buy groceries", tags=[Tag("shopping")], due_at=past),
            _task(2, "Write report", status=TaskStatus.DONE, tags=[Tag("work")]),
            _task(3, "Call doctor", tags=[Tag("health")], due_at=future),
            _task(4, "Review PR", tags=[Tag("work"), Tag("dev")]),
        ]

    def test_no_filter_returns_all(self, tasks):
        page = apply_query(tasks, TaskQuery(), NOW)
        assert page.total == 4

    def test_filter_by_status_pending(self, tasks):
        page = apply_query(tasks, TaskQuery(status=TaskStatus.PENDING), NOW)
        assert page.total == 3
        assert all(t.status == TaskStatus.PENDING for t in page.items)

    def test_filter_by_status_done(self, tasks):
        page = apply_query(tasks, TaskQuery(status=TaskStatus.DONE), NOW)
        assert page.total == 1
        assert page.items[0].id == 2

    def test_filter_by_tag(self, tasks):
        page = apply_query(tasks, TaskQuery(tag="work"), NOW)
        ids = {t.id for t in page.items}
        assert ids == {2, 4}

    def test_filter_by_search(self, tasks):
        page = apply_query(tasks, TaskQuery(search="report"), NOW)
        assert page.total == 1
        assert page.items[0].id == 2

    def test_search_case_insensitive(self, tasks):
        page = apply_query(tasks, TaskQuery(search="BUY"), NOW)
        assert page.total == 1

    def test_filter_overdue_true(self, tasks):
        page = apply_query(tasks, TaskQuery(overdue=True), NOW)
        assert page.total == 1
        assert page.items[0].id == 1

    def test_filter_overdue_false(self, tasks):
        page = apply_query(tasks, TaskQuery(overdue=False), NOW)
        # Tasks 2 (done), 3 (future due), 4 (no due) are not overdue
        assert page.total == 3

    def test_combined_filters(self, tasks):
        page = apply_query(tasks, TaskQuery(status=TaskStatus.PENDING, tag="work"), NOW)
        assert page.total == 1
        assert page.items[0].id == 4


# ── apply_query — sorting ───────────────────────────────────────────────

class TestApplyQuerySorting:
    def test_sort_by_title(self):
        tasks = [_task(1, "Banana"), _task(2, "Apple"), _task(3, "Cherry")]
        page = apply_query(tasks, TaskQuery(sort="title"), NOW)
        assert [t.title for t in page.items] == ["Apple", "Banana", "Cherry"]

    def test_sort_by_title_descending(self):
        tasks = [_task(1, "Banana"), _task(2, "Apple"), _task(3, "Cherry")]
        page = apply_query(tasks, TaskQuery(sort="title", descending=True), NOW)
        assert [t.title for t in page.items] == ["Cherry", "Banana", "Apple"]

    def test_sort_by_priority(self):
        tasks = [
            _task(1, priority=TaskPriority.LOW),
            _task(2, priority=TaskPriority.HIGH),
            _task(3, priority=TaskPriority.MEDIUM),
        ]
        page = apply_query(tasks, TaskQuery(sort="priority"), NOW)
        assert [t.priority for t in page.items] == [
            TaskPriority.HIGH, TaskPriority.MEDIUM, TaskPriority.LOW
        ]

    def test_sort_by_created_at(self):
        t1 = _task(1, created_at=NOW - timedelta(hours=2))
        t2 = _task(2, created_at=NOW - timedelta(hours=1))
        t3 = _task(3, created_at=NOW)
        page = apply_query([t3, t1, t2], TaskQuery(sort="created_at"), NOW)
        assert [t.id for t in page.items] == [1, 2, 3]

