class TestApplyQueryPagination:
    @pytest.fixture
    def tasks(self):
        return [_task(i, title=f"Task {i}",
                      created_at=NOW + timedelta(seconds=i)) for i in range(1, 11)]

    def test_limit(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=3), NOW)
        assert len(page.items) == 3
        assert page.total == 10
        assert page.has_more is True

    def test_offset(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=3, offset=7), NOW)
        assert len(page.items) == 3
        assert page.has_more is False

    def test_offset_past_end(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=5, offset=20), NOW)
        assert page.items == []
        assert page.total == 10
        assert page.has_more is False

    def test_has_more_exact_boundary(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=10), NOW)
        assert page.has_more is False
        assert len(page.items) == 10


# ── TaskPage ────────────────────────────────────────────────────────────

class TestTaskPage:
    def test_has_more_true(self):
        page = TaskPage(items=[_task(1)], total=5, limit=2, offset=0)
